  attentionWeight: number;
  source: string;
  evidence: {
    likes?: number;
    saves?: number;
    watchTime?: number;
    highlights?: number;
    visits?: number;
  };
  firstSeen: string;
  lastActive: string;
  cluster?: string;
  createdAt: string;
  activityScore: 'High' | 'Medium' | 'Low';
  sharedCount: number;
  trending: boolean;
  parentId?: string;
  children?: string[];
}

